favicon_etag = hashlib.sha1(favicon).hexdigest()
favicon_b64 = base64.b64encode(favicon).decode("utf-8")


def favicon_serve(request):
    return HttpResponse(
        favicon, content_type="image/x-icon", headers={"Etag": favicon_etag}
    )


